--
-- Table structure for table `live_video_comments`
--

CREATE TABLE `live_video_comments` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `live_video_item_id` bigint(20) UNSIGNED DEFAULT NULL,
  `comment` text DEFAULT NULL,
  `user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `video_id` bigint(20) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `live_video_items`
--

CREATE TABLE `live_video_items` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `live_video_id` bigint(20) UNSIGNED DEFAULT NULL,
  `transferred_from_item_id` bigint(20) UNSIGNED DEFAULT NULL,
  `transfer_origin_item_id` bigint(20) UNSIGNED DEFAULT NULL,
  `status` enum('pending','working','finished') DEFAULT 'pending',
  `end_at` timestamp NULL DEFAULT NULL,
  `image` text DEFAULT NULL,
  `information` text DEFAULT NULL,
  `quantity` double DEFAULT NULL,
  `piece_multiplier_number` varchar(255) DEFAULT NULL,
  `bidding` double DEFAULT NULL,
  `finished_price` double DEFAULT NULL,
  `user_finished_id` bigint(20) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `title_ar` text DEFAULT NULL,
  `information_ar` text DEFAULT NULL,
  `user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `seller_id` bigint(20) UNSIGNED DEFAULT NULL,
  `address` text DEFAULT NULL,
  `video` varchar(255) DEFAULT NULL,
  `show_partner_name` tinyint(1) DEFAULT 0,
  `winner_video` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

