INSERT INTO `pages` (`id`, `name`, `description`, `image`, `created_at`, `updated_at`) VALUES
(1, '{\"en\":\"About us\",\"ar\":\"\\u0645\\u0646 \\u0646\\u062d\\u0646\"}', '{\"en\":\"Mazadat is a specialized online marketplace dedicated to livestock auctions, with a primary focus on sheep trading. Our platform connects breeders, traders, and buyers in a trusted environment where high-quality livestock can be bought and sold \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0648\\u0634\\u0641\\u0627\\u0641\\u064a\\u0629.\\r\\n\\r\\nWe aim to simplify the traditional livestock market by providing a digital auction experience that is fast, reliable, and accessible from anywhere. Through Mazadat, users can showcase their livestock, participate in live bidding, and reach a wider audience without the limitations of physical markets.\\r\\n\\r\\nOur mission is to modernize livestock trading by combining industry knowledge with advanced technology, creating a safe and efficient marketplace for everyone involved.\",\"ar\":\"\\u0645\\u0632\\u0627\\u062f\\u0627\\u062a \\u0647\\u064a \\u0645\\u0646\\u0635\\u0629 \\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a\\u0629 \\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\u0641\\u064a \\u0645\\u0632\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0645\\u0648\\u0627\\u0634\\u064a\\u060c \\u0645\\u0639 \\u062a\\u0631\\u0643\\u064a\\u0632 \\u0623\\u0633\\u0627\\u0633\\u064a \\u0639\\u0644\\u0649 \\u062a\\u062c\\u0627\\u0631\\u0629 \\u0627\\u0644\\u063a\\u0646\\u0645. \\u062a\\u0631\\u0628\\u0637 \\u0627\\u0644\\u0645\\u0646\\u0635\\u0629 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u0645\\u0631\\u0628\\u064a\\u0646 \\u0648\\u0627\\u0644\\u062a\\u062c\\u0627\\u0631 \\u0648\\u0627\\u0644\\u0645\\u0634\\u062a\\u0631\\u064a\\u0646 \\u0641\\u064a \\u0628\\u064a\\u0626\\u0629 \\u0645\\u0648\\u062b\\u0648\\u0642\\u0629 \\u062a\\u062a\\u064a\\u062d \\u0628\\u064a\\u0639 \\u0648\\u0634\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0634\\u064a \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0648\\u0634\\u0641\\u0627\\u0641\\u064a\\u0629.\\r