  `order_id` int(11) DEFAULT NULL COMMENT 'Should be the foreign key for items',
  `store_id` int(11) NOT NULL COMMENT 'Map to ivp_store',
  `test_mode` tinyint(1) NOT NULL DEFAULT 0,
  `amount` decimal(8,2) NOT NULL COMMENT 'Map to ivp_amount the total or purchase',
  `description` varchar(255) NOT NULL COMMENT 'Description should be limit to 64',
  `success_url` varchar(255) NOT NULL COMMENT 'The success URL',
  `canceled_url` varchar(255) NOT NULL COMMENT 'The canceled URL',
  `declined_url` varchar(255) NOT NULL COMMENT 'The declined URL',
  `billing_fname` varchar(255) DEFAULT NULL COMMENT 'Billing first name',
  `billing_sname` varchar(255) DEFAULT NULL COMMENT 'Billing sur name',
  `billing_address_1` varchar(255) DEFAULT NULL COMMENT 'Billing address 1',
  `billing_address_2` varchar(255) DEFAULT NULL COMMENT 'Billing address 2',
  `billing_city` varchar(255) DEFAULT NULL COMMENT 'Billing city',
  `billing_region` varchar(255) DEFAULT NULL COMMENT 'Billing region',
  `billing_zip` varchar(255) DEFAULT NULL COMMENT 'Billing zip',
  `billing_country` varchar(255) DEFAULT NULL COMMENT 'Billing country',
  `billing_email` varchar(255) DEFAULT NULL COMMENT 'Billing email',
  `lang_code` varchar(255) DEFAULT NULL COMMENT 'Transaction Request lang',
  `trx_reference` varchar(255) DEFAULT NULL COMMENT 'The transaction reference',
  `approved` tinyint(1) DEFAULT NULL COMMENT 'The transaction status is approved or failed',
  `response` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'The transaction response',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'The transaction status is updated or not',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `users`
--

CREATE TABLE `users` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `user_name` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `national_id` varchar(32) DEFAULT NULL,
  `city_id` bigint(20) UNSIGNED DEFAULT NULL,
  `nafath_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) DEFAULT NULL,
  `gender` enum('male','female') NOT NULL,
  `birth_date` date DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `otp` varchar(255) DEFAULT NULL,
  `expire_at` timestamp NULL DEFAULT NULL,
  `bio` text DEFAULT NULL,
  `password_otp` varchar(255) DEFAULT NULL,
  `facebook_id` varchar(255) DEFAULT NULL,
  `google_id` varchar(255) DEFAULT NULL,
  `apple_id` varchar(255) DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `fcm_token` text DEFAULT NULL,
  `user_type` enum('buyer','vendor','buyer_vendor','seller') NOT NULL DEFAULT 'buyer',
  `account_type` enum('individual','company') DEFAULT NULL,
  `is_active` int(11) NOT NULL DEFAULT 1,
  `app_lang` enum('en','ar') NOT NULL DEFAULT 'en',
  `admin_id` bigint(20) UNSIGNED DEFAULT NULL,
  `is_verified` tinyint(1) NOT NULL DEFAULT 0,
  `commercial_register` varchar(255) DEFAULT NULL,
  `tax_certificate` varchar(255) DEFAULT NULL,
  `license` varchar(255) DEFAULT NULL,
  `wallet_balance` double NOT NULL DEFAULT 0,
  `is_main` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

